package bittorrent

// Cross-client interoperability scenarios (BT-02). Every test here is opt-in:
// see crossclient_lab_test.go. The fixtures are generated by this package's own
// v1 builder, the peer is a pinned qBittorrent/libtorrent in a container, and
// nothing outside the host is contacted: no trackers, no DHT, no PEX, no LSD.

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/anacrolix/torrent/bencode"
	"github.com/anacrolix/torrent/metainfo"
)

// labFixtureName is the torrent's name (also its payload directory).
const labFixtureName = "labfixture"

// labFixture builds a v1 torrent whose layout is deliberately awkward:
//
//	a.bin      5000 bytes  — ragged, ends in the middle of piece 0
//	empty.bin     0 bytes  — a zero-length entry in the file list
//	b.bin     40000 bytes  — multi-piece, starts mid-piece
//	c.bin      9000 bytes  — ragged again, shares an edge piece
//
// With 16 KiB pieces this gives a shared edge piece (a/b), a file that spans
// three pieces, and a layout where a selection boundary falls inside a piece.
func labFixture(t *testing.T) (files map[string][]byte, mi *metainfo.MetaInfo, torrentPath string) {
	t.Helper()
	files = map[string][]byte{
		"a.bin":     patterned(5000, 41),
		"empty.bin": {},
		"b.bin":     patterned(40000, 43),
		"c.bin":     patterned(9000, 47),
	}
	parent := t.TempDir()
	dir := filepath.Join(parent, labFixtureName)
	for rel, content := range files {
		p := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, content, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	info := metainfo.Info{PieceLength: 16 << 10}
	if err := info.BuildFromFilePath(dir); err != nil {
		t.Fatalf("build fixture metainfo: %v", err)
	}
	mi = &metainfo.MetaInfo{InfoBytes: bencode.MustMarshal(info)}
	mi.SetDefaults()
	var buf bytes.Buffer
	if err := mi.Write(&buf); err != nil {
		t.Fatal(err)
	}
	torrentPath = filepath.Join(t.TempDir(), labFixtureName+".torrent")
	if err := os.WriteFile(torrentPath, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
	return files, mi, torrentPath
}

// labPaths returns the staging-relative paths of the fixture's real files.
func labPaths() []string {
	return []string{
		labFixtureName + "/a.bin",
		labFixtureName + "/b.bin",
		labFixtureName + "/c.bin",
	}
}

// fetchWithTrace runs Fetch while sampling the torrent's peer state once a
// second, so a stalled cross-client transfer says where it stalled (never
// dialled, dialling, connected and stuck) instead of only timing out.
func fetchWithTrace(t *testing.T, sess *Session, ctx context.Context, src string, selection []string) (Capture, error) {
	t.Helper()
	type result struct {
		cap Capture
		err error
	}
	done := make(chan result, 1)
	go func() {
		cap, err := sess.Fetch(ctx, src, selection)
		done <- result{cap: cap, err: err}
	}()
	tick := time.NewTicker(time.Second)
	defer tick.Stop()
	var lastLine string
	for {
		select {
		case res := <-done:
			return res.cap, res.err
		case <-tick.C:
			for _, tor := range sess.client.Torrents() {
				st := tor.Stats()
				line := fmt.Sprintf("peers active=%d halfopen=%d pending=%d total=%d seeds=%d bytesReadData=%d",
					st.ActivePeers, st.HalfOpenPeers, st.PendingPeers, st.TotalPeers,
					st.ConnectedSeeders, st.BytesReadData.Int64())
				if line != lastLine {
					t.Logf("trace: %s", line)
					lastLine = line
				}
			}
		}
	}
}

// TestCrossClientQbtSeedsProvenanceFetches is direction A: the reference client
// seeds, Provenance fetches a selection over the peer wire, verifies it, and
// restarts from its own persisted state without a peer.
//
// It covers encoder interoperability (our metainfo is accepted by libtorrent),
// peer wire interoperability (a real handshake, piece requests and uploads in
// both directions of the connection) and selective storage interoperability
// (Provenance takes two of four entries from a fully seeded torrent).
func TestCrossClientQbtSeedsProvenanceFetches(t *testing.T) {
	requireCrossClientLab(t)
	l := newQbtLab(t)
	l.prepare()
	l.actualPort = l.listenPort(t)
	t.Logf("lab: qBittorrent %s, libtorrent %s, container %s, peer port %d",
		l.appVersion(t), l.libtorrentVersion(t), l.ip, l.actualPort)

	files, mi, torrentPath := labFixture(t)
	l.seedPayload(labFixtureName, files)
	l.addTorrent(torrentPath, "/data/seed", false)
	done := l.waitComplete(strings.ToLower(mi.HashInfoBytes().HexString()), 120*time.Second)
	t.Logf("lab: reference client reports progress=%.3f state=%s", done.Progress, done.State)

	// Offline inspection lists the empty entry without pretending it is content
	// to fetch: the file list is metainfo, not a promise about the wire.
	info, err := Inspect(context.Background(), torrentPath, InspectConfig{Discovery: DiscoveryDirect})
	if err != nil {
		t.Fatalf("inspect fixture: %v", err)
	}
	if len(info.Files) != 4 {
		t.Fatalf("inspect file list = %+v, want four entries", info.Files)
	}
	var emptySeen bool
	for _, f := range info.Files {
		if strings.HasSuffix(f.Path, "empty.bin") {
			emptySeen = true
			if f.Length != 0 {
				t.Errorf("empty.bin length = %d, want 0", f.Length)
			}
		}
	}
	if !emptySeen {
		t.Errorf("inspect file list = %+v, want the zero-length entry listed", info.Files)
	}

	staging := t.TempDir()
	cfg := Config{
		StagingDir:      staging,
		Peers:           []string{l.peerAddr()},
		Discovery:       DiscoveryDirect,
		MetadataTimeout: 60 * time.Second,
		Timeout:         180 * time.Second,
		MaxPeers:        8,
	}
	sess := discSession(t, cfg)
	ctx, cancel := context.WithTimeout(context.Background(), 180*time.Second)
	defer cancel()
	cap, err := fetchWithTrace(t, sess, ctx, torrentPath, []string{labFixtureName + "/a.bin", labFixtureName + "/b.bin"})
	if err != nil {
		for _, tor := range sess.client.Torrents() {
			st := tor.Stats()
			t.Logf("our torrent stats: peers(active=%d pending=%d total=%d connectedSeeders=%d) bytesReadData=%d chunksReadUseful=%d",
				st.ActivePeers, st.PendingPeers, st.TotalPeers, st.ConnectedSeeders,
				st.BytesReadData.Int64(), st.ChunksReadUseful.Int64())
		}
		l.dumpTorrent(t, strings.ToLower(mi.HashInfoBytes().HexString()))
		t.Fatalf("fetch from qBittorrent: %v", err)
	}
	if len(cap.Assets) != 2 {
		t.Fatalf("captured %d assets, want 2: %+v", len(cap.Assets), cap.Assets)
	}
	for _, asset := range cap.Assets {
		want := files[strings.TrimPrefix(asset.Path, labFixtureName+"/")]
		if asset.SHA256 != sha256Hex(want) {
			t.Errorf("%s digest = %s, want %s", asset.Path, asset.SHA256, sha256Hex(want))
		}
	}
	if cap.BytesRead <= 0 {
		t.Errorf("BytesRead = %d; the bytes did not come from the reference client", cap.BytesRead)
	}
	// The unselected neighbours are not captured, even the one sharing a piece.
	for _, asset := range cap.Assets {
		if strings.HasSuffix(asset.Path, "c.bin") {
			t.Errorf("unselected file was captured: %s", asset.Path)
		}
	}
	if got := len(captureManifests(t, staging)); got != 1 {
		t.Errorf("%d capture manifests, want 1", got)
	}
	if err := sess.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	// Restart: no peers at all, and the capture is still reconciled from the
	// bytes the reference client served, verified against the persisted metainfo.
	offline := cfg
	offline.Peers = nil
	offline.Timeout = 60 * time.Second
	sess2 := discSession(t, offline)
	ctx2, cancel2 := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel2()
	cap2, err := sess2.Fetch(ctx2, torrentPath, []string{labFixtureName + "/a.bin", labFixtureName + "/b.bin"})
	if err != nil {
		t.Fatalf("offline restart: %v", err)
	}
	if !cap2.Reconciled {
		t.Error("restart did not reconcile the existing capture")
	}
	if cap2.BytesRead != 0 {
		t.Errorf("restart read %d bytes from peers, want 0", cap2.BytesRead)
	}
	if cap2.CaptureKey != cap.CaptureKey {
		t.Errorf("capture key changed across restart: %s -> %s", cap.CaptureKey, cap2.CaptureKey)
	}
}

// TestCrossClientSelectiveSeedServesOurSelection is direction A with a
// selectively-storing reference client: qBittorrent holds only one of the
// fixture's files and skips the rest by priority. Provenance must be able to
// fetch that one file, and must fail bounded — not publish — for a file the
// peer does not have.
func TestCrossClientSelectiveSeedServesOurSelection(t *testing.T) {
	requireCrossClientLab(t)
	t.Skip("blocked on an ordering bug in the lab, not on the adapter: see docs/CROSSCLIENT.md. " +
		"Measured on qBittorrent v5.3.0/libtorrent 2.1.2: a peer seeded with only b.bin reports " +
		"stalledDL progress=0.333 amount_left=32768 and never completes, because pieces 0 and 2 of " +
		"this fixture also cover a.bin and c.bin (the ragged-edge case the fixture exists to create). " +
		"The reference client therefore cannot serve a selection that shares edge pieces with files " +
		"it does not hold; the row stays unsupported until the lab asserts that directly.")
	l := newQbtLab(t)
	l.prepare()
	l.actualPort = l.listenPort(t)

	files, mi, torrentPath := labFixture(t)
	// Only b.bin exists in the reference client's storage.
	l.seedPayload(labFixtureName, map[string][]byte{"b.bin": files["b.bin"]})
	l.addTorrent(torrentPath, "/data/seed", true)

	hash := strings.ToLower(mi.HashInfoBytes().HexString())
	// The add call returns before the torrent is loaded; per-file priorities
	// answer 404 (or a confusing 400) until it is.
	l.waitTorrent(hash, "known", 60*time.Second, func(qbtTorrent) bool { return true })
	// By name, because the WebUI's file indices are the torrent's order and the
	// lab must not depend on which of the two it happens to be.
	l.setFileNamePriorities(hash, map[string]int{
		"labfixture/a.bin":     0,
		"labfixture/empty.bin": 0,
		"labfixture/b.bin":     1,
		"labfixture/c.bin":     0,
	})
	if _, err := l.api("POST", "/api/v2/torrents/start", map[string][]string{"hashes": {hash}}); err != nil {
		// qBittorrent 4.x calls this "resume"; 5.x renamed it.
		if _, err2 := l.api("POST", "/api/v2/torrents/resume", map[string][]string{"hashes": {hash}}); err2 != nil {
			t.Fatalf("start after setting priorities: %v / %v", err, err2)
		}
	}
	l.waitComplete(hash, 120*time.Second)

	staging := t.TempDir()
	sess := discSession(t, Config{
		StagingDir:      staging,
		Peers:           []string{l.peerAddr()},
		Discovery:       DiscoveryDirect,
		MetadataTimeout: 60 * time.Second,
		Timeout:         180 * time.Second,
		MaxPeers:        8,
	})
	ctx, cancel := context.WithTimeout(context.Background(), 180*time.Second)
	defer cancel()
	cap, err := sess.Fetch(ctx, torrentPath, []string{labFixtureName + "/b.bin"})
	if err != nil {
		t.Fatalf("fetch the selection the peer has: %v", err)
	}
	if len(cap.Assets) != 1 || cap.Assets[0].SHA256 != sha256Hex(files["b.bin"]) {
		t.Fatalf("capture = %+v, want only b.bin with its fixture digest", cap.Assets)
	}

	// The peer deliberately does not have a.bin. The attempt must be bounded and
	// publish nothing: no capture, no second manifest, payload still pending.
	before := len(captureManifests(t, staging))
	short := Config{
		StagingDir:      t.TempDir(),
		Peers:           []string{l.peerAddr()},
		Discovery:       DiscoveryDirect,
		MetadataTimeout: 60 * time.Second,
		Timeout:         8 * time.Second,
		MaxPeers:        8,
	}
	sess2 := discSession(t, short)
	ctx2, cancel2 := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel2()
	_, err = sess2.Fetch(ctx2, torrentPath, []string{labFixtureName + "/a.bin"})
	if err == nil {
		t.Fatal("fetch of a file the reference client does not have succeeded")
	}
	if !errors.Is(err, ErrTransferTimeout) {
		t.Errorf("error = %v, want a bounded transfer timeout", err)
	}
	if got := len(captureManifests(t, short.StagingDir)); got != 0 {
		t.Errorf("failed fetch published %d capture manifests", got)
	}
	if got := len(captureManifests(t, staging)); got != before {
		t.Errorf("first staging root changed: %d -> %d manifests", before, got)
	}
}

// TestCrossClientProvenanceSeedsQbtDownloads is direction B: Provenance is the
// seeder and the reference client downloads, with no tracker involved — the
// container is given the seeder's address as a BEP 9 peer hint (magnet x.pe),
// which is the only address it can act on.
//
// The container runs on the host network for this direction only: Provenance's
// direct profile binds its peer listener to loopback, so the container has to
// share that loopback to reach it.
func TestCrossClientProvenanceSeedsQbtDownloads(t *testing.T) {
	requireCrossClientLab(t)
	t.Skip("blocked on the reference client's own local-peer IPC: on the host network namespace the " +
		"second start exits with \"LocalPeer: failed to connect to server.\" before the WebUI binds, " +
		"so the direction was never exercised. See docs/CROSSCLIENT.md.")
	files, mi, torrentPath := labFixture(t)

	// Stage the whole torrent so Provenance has something to seed: this is the
	// "verified payload already on disk" path, not a download.
	staging := t.TempDir()
	for rel, content := range files {
		p := filepath.Join(staging, labFixtureName, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, content, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	sess := discSession(t, Config{
		StagingDir:      staging,
		Discovery:       DiscoveryDirect,
		MetadataTimeout: 60 * time.Second,
		Timeout:         300 * time.Second,
		KeepSeeding:     true,
		MaxPeers:        8,
	})
	seedCtx, stopSeeding := context.WithCancel(context.Background())

	type fetchResult struct {
		cap Capture
		err error
	}
	served := make(chan fetchResult, 1)
	go func() {
		fctx, fcancel := context.WithTimeout(seedCtx, 300*time.Second)
		defer fcancel()
		cap, err := sess.Fetch(fctx, torrentPath, labPaths())
		served <- fetchResult{cap: cap, err: err}
	}()

	// Wait until the seeder has verified its payload and is serving.
	waitFor(t, "the provenance seeder to start", 60*time.Second, func() bool {
		return jobSeedingReady(staging, strings.ToLower(mi.HashInfoBytes().HexString()))
	})
	port := sess.client.LocalPort()
	if port == 0 {
		t.Fatal("seeder has no listening port")
	}
	t.Logf("lab: provenance seeding on loopback port %d", port)

	l := newQbtLabOpts(t, labOptions{hostNetwork: true})
	l.prepare()
	t.Logf("lab: qBittorrent %s, libtorrent %s (host network, loopback only)",
		l.appVersion(t), l.libtorrentVersion(t))

	magnet := "magnet:?xt=urn:btih:" + mi.HashInfoBytes().HexString() +
		"&dn=" + labFixtureName +
		"&x.pe=" + net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	l.addMagnet(magnet, "/data/downloads")

	hash := strings.ToLower(mi.HashInfoBytes().HexString())
	done := l.waitComplete(hash, 240*time.Second)
	t.Logf("lab: reference client finished: progress=%.3f state=%s downloaded=%d", done.Progress, done.State, done.Downloaded)

	for rel, want := range files {
		p := l.downloadedPath(labFixtureName, rel)
		got, err := os.ReadFile(p)
		if err != nil {
			t.Errorf("reference client did not write %s: %v", rel, err)
			continue
		}
		if !bytes.Equal(got, want) {
			t.Errorf("%s: downloaded bytes differ from the fixture", rel)
		}
	}

	// The reference client finished; stop seeding and collect Provenance's own
	// capture of what it served. The stop is idempotent and also runs from a
	// cleanup, so the seeder goroutine is finished before the temp dirs go away.
	var stopOnce sync.Once
	var stopResult fetchResult
	stopSeedingAndCollect := func() fetchResult {
		stopOnce.Do(func() {
			stopSeeding()
			select {
			case stopResult = <-served:
			case <-time.After(120 * time.Second):
				stopResult = fetchResult{err: errors.New("seeder did not stop after cancellation")}
			}
		})
		return stopResult
	}
	t.Cleanup(func() { _ = stopSeedingAndCollect() })

	res := stopSeedingAndCollect()
	if res.err != nil {
		t.Fatalf("seeder fetch: %v", res.err)
	}
	if len(res.cap.Assets) != 3 {
		t.Errorf("seeder captured %d assets, want 3: %+v", len(res.cap.Assets), res.cap.Assets)
	}
}
